-- Generated by Toasty CLI from the registered models.
-- The initial migration tolerates the identical tables created by the earlier
-- prototype, preserving existing data while Toasty starts tracking versions.
CREATE TABLE IF NOT EXISTS "identity_transaction_guard" (
    "id" INTEGER NOT NULL,
    "revision" BIGINT NOT NULL,
    PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "identity_records" (
    "id" TEXT NOT NULL,
    "payload" TEXT NOT NULL,
    PRIMARY KEY ("id")
);
